"""Freeze explicit source-text reviews, then verify edits separately from inference."""
import json,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.acre_pilot.span_mapping import locate
rows=json.loads((ROOT/'results/acre_pilot/boolean_extended.json').read_text());reviews=[]

def add(gid,node,old,new,factor,reason,state='no'):
    c=next(c for c in rows if (c['guideline_id'],c['node']['index'])==(gid,node))
    source=next(v for v in c['cases'] if v['path'][-2]['decision_outcome']==state)
    a,b=locate(source['patient'],old)
    # All preceding original conditions are explicitly stated before this local
    # resource clause, reviewed against the source signed path. Whole context is
    # retained to disambiguate repeated or compound ancestor observations.
    context=source['patient'][:a].strip()
    if not context and c['ancestors']:raise ValueError('no_independent_ancestor_context')
    positive,negative=(new,old) if state=='no' else (old,new)
    reviews.append({'pair_id':f'v2_{gid}_{node}','guideline_id':gid,'node_index':node,'source_case_id':f'{gid}:{source["path_id"]}','source_path_id':source['path_id'],'old':old,'new':new,'positive_pattern':re.escape(positive),'negative_pattern':re.escape(negative),'single_factor':factor,'ancestor_evidence':[[context] for _ in c['ancestors']],'original_path_source_text_reviewed':True,'clinical_consistency':True,'incompatible_actions':True,'incompatibility_reason':reason,'semantic_review_scope':'Single explicitly documented availability/feasibility factor; all prior signed conditions checked against original context. No medical efficacy claim or clinical expert certification.'})

