# Numerical conditions with exact measurements and synchronized interpretations.
D=Path(json.loads((ROOT/'configs/datasets.json').read_text())['MEGA-CDP']['path'])
paths={r['guideline_id']:r['paths'] for r in [json.loads(v) for v in (D/'train_val/case_paths.jsonl').read_text().splitlines()]}
cases={(r['guideline_id'],r['path_id']):r['text'] for r in [json.loads(v) for v in (D/'train_val/vignette_cases.jsonl').read_text().splitlines()]}
def numeric(gid,node,pid,old,new,spec,factor,reason,ancestor_checks=()):
    patient=cases[(gid,pid)];path=paths[gid][pid-1];a,b=locate(patient,old);context=patient[:a].strip()
    reviews.append({'pair_id':f'v2_{gid}_{node}','guideline_id':gid,'node_index':node,'source_path_id':pid,'source_case_id':f'{gid}:{pid}','old':old,'new':new,'numeric_spec':spec,'numeric_ancestor_checks':list(ancestor_checks),'single_factor':factor,'ancestor_evidence':[[context] for _ in path[:-2]],'original_path_source_text_reviewed':True,'clinical_consistency':True,'incompatible_actions':True,'incompatibility_reason':reason,'semantic_review_scope':'Original source path and clinical statements checked; single measurement and its threshold interpretation change together. Numerical route verified independently of model.'})
